(function () {
  var Ajv = require('ajv');
  var spec = JSON.parse(pm.collectionVariables.get('contract'));
  var ajv = new Ajv({ allErrors: true, unknownFormats: 'ignore', schemaId: 'auto', validateSchema: false, logger: false });
  ajv.addSchema(spec, 'spec');
  var ref = function (name) { return { $ref: 'spec#/components/schemas/' + name }; };
  var body = function () { try { return pm.response.json(); } catch (e) { return undefined; } };
  var notJson = function () { return 'Body is not JSON: ' + String(pm.response.text()).slice(0, 80); };
  var isObj = function (b) { return b !== undefined && b !== null && typeof b === 'object' && !Array.isArray(b); };
  var validate = function (schema, value) {
    if (value === undefined) { return notJson(); }
    return ajv.validate(schema, value) ? '' : ajv.errorsText();
  };
  var extrasOf = function (name, value) {
    var documented = spec.components.schemas[name].properties || {};
    return Object.keys(value).filter(function (k) { return !(k in documented); });
  };
  var status = function (label, code) {
    pm.test(label + ' returns ' + code, function () { pm.response.to.have.status(code); });
  };
  var header = function (label, name) {
    pm.test(label + ' sends the ' + name + ' header', function () { pm.response.to.have.header(name); });
  };
  var schema = function (label, name) {
    pm.test(label + ' body matches ' + name, function () {
      var msg = validate(ref(name), body());
      pm.expect(msg, msg).to.equal('');
    });
  };
  var noExtras = function (label, name) {
    pm.test(label + ' has no undocumented fields', function () {
      var b = body();
      pm.expect(isObj(b), notJson()).to.be.true;
      var extras = extrasOf(name, b);
      pm.expect(extras, 'Undocumented: ' + extras.join(', ')).to.be.empty;
    });
  };
  var ok = function (label, code, name, headers) {
    status(label, code);
    (headers || []).forEach(function (h) { header(label, h); });
    schema(label, name);
    noExtras(label, name);
  };
  var list = function (label, name) {
    pm.test(label + ' returns a JSON array', function () {
      pm.expect(Array.isArray(body()), notJson()).to.be.true;
    });
    pm.test('Every item in ' + label + ' matches ' + name, function () {
      var arr = body();
      pm.expect(Array.isArray(arr), notJson()).to.be.true;
      var bad = [];
      arr.forEach(function (it, i) { var m = validate(ref(name), it); if (m) { bad.push('item ' + i + ': ' + m); } });
      pm.expect(bad, bad.slice(0, 3).join(' | ')).to.be.empty;
    });
    pm.test('Every item in ' + label + ' has no undocumented fields', function () {
      var arr = body();
      pm.expect(Array.isArray(arr), notJson()).to.be.true;
      var bad = [];
      arr.forEach(function (it, i) {
        if (isObj(it)) { var x = extrasOf(name, it); if (x.length) { bad.push('item ' + i + ': ' + x.join(', ')); } }
      });
      pm.expect(bad, bad.slice(0, 3).join(' | ')).to.be.empty;
    });
  };
  var err = function (label, code) {
    status(label, code);
    schema(label + ' error', 'ErrorResponse');
    pm.test(label + ' error body status field equals ' + code, function () {
      var b = body();
      pm.expect(isObj(b) ? b.status : undefined).to.equal(code);
    });
    pm.test(label + ' error body path is the requested path', function () {
      var b = body();
      var asked = pm.variables.replaceIn(pm.request.url.getPath());
      pm.expect(isObj(b) ? b.path : undefined).to.equal(asked);
    });
  };
  var inst = function (c) { return c.instructorId !== undefined ? c.instructorId : c.instructor; };
  return { body: body, ref: ref, validate: validate, status: status, header: header, schema: schema,
           noExtras: noExtras, ok: ok, list: list, err: err, inst: inst, isObj: isObj, notJson: notJson };
})()
